var DATA = {"locale": "de-DE vs en-US", "behavior": "Date string parsing", "expected": "10/11/2026 parses per the user locale", "samples": "10/11/2026|2026-10-21|21.10.2026"};
console.log("Locale: " + DATA.locale);
console.log("Behavior: " + DATA.behavior);
var samples = DATA.samples.split("|").map(function (s) { return s.trim(); });
try {
  var nf = new Intl.NumberFormat(DATA.locale);
  var df = new Intl.DateTimeFormat(DATA.locale, { dateStyle: "full" });
  samples.forEach(function (s, i) {
    var num = Number(s);
    var out = isNaN(num) ? s : nf.format(num);
    console.log("  sample " + (i + 1) + ": " + s + " -> " + out);
  });
  console.log("  date sample: " + df.format(new Date("2026-10-21T12:00:00Z")));
} catch (e) { console.log("  Intl unavailable: " + e.message); }
console.log("Expected: " + DATA.expected);
console.log("RESULT: locale rendering demonstrated for " + DATA.locale + ".");

